def get_segment_wave(waveform, sr, start, end, min_len=0.5):
    total_dur = waveform.shape[1] / sr
    if end - start < min_len:
        center = (start + end) / 2.0
        start = max(0.0, center - min_len / 2.0)
        end = min(total_dur, center + min_len / 2.0)
    s = int(start * sr)
    e = int(end * sr)
    if e <= s:
        e = min(waveform.shape[1], s + int(min_len * sr))
    return waveform[:, s:e]


